function meetGate(ch=state.currentChapter){const list=getAvailableEncounters(state),encounter=list.find(e=>e.available&&!e.defeated&&e.chapterId===ch&&e.recordKey===state.activeQuestKey)??list.find(e=>e.available&&!e.defeated&&e.chapterId===ch);if(encounter){beginEncounter(encounter);return;}const activeRecord=state.questStates[state.activeQuestKey],resumeKey=activeRecord&&questById[activeRecord.questId]?.chapterId===ch&&!activeRecord.completed?state.activeQuestKey:chapterResumeKey(state,ch),qs=state.questStates[resumeKey],q=qs&&questById[qs.questId];if(q&&!qs.completed){resumeFromChapter(resumeKey);return;}if(bossAvailable(state,ch)&&!state.bossStates[ch]?.completed){ui.bossId=ch;nav('boss');return;}showDialog('洞窟の奥の声',[p('いまは新しい戦いはありません。町の人に依頼を聞くか、終えた用事を報告しよう。')],[btn('洞窟に戻る',()=>modal.close(),'primary')]);}
function beginEncounter(encounter){worldControls?.stop();if(act({type:'RPG_BATTLE_START',encounterId:encounter.id},{view:'combat'})){ui.battleQuestKey=encounter.recordKey;window.scrollTo(0,0);}}
function continueAfterBattle(){const battle=state.rpg?.battle;if(battle?.fieldKind==='desert'&&battle.status==='fled')ui.desertGrace=8;const record=state.questStates[battle?.recordKey??ui.battleQuestKey??state.activeQuestKey],q=record&&questById[record.questId];if(battle?.kind!=='field'&&battle?.status!=='fled'&&q&&!record.completed&&!entryEncounter()){openQuestPhone(q);return;}ui.view='world';render();window.scrollTo(0,0);}
function renderCombatView(main){
 const battle=state.rpg?.battle;
 if(battle?.status==='active'&&battle.turn===1&&ui.acknowledgedBattleId!==battle.id){
  encounterIntro=mountEncounterIntro({document,state,onStart:()=>{
   if(ui.view!=='combat'||state.rpg?.battle?.id!==battle.id||state.rpg.battle.status!=='active')return;
   ui.acknowledgedBattleId=battle.id;ui.combatReadyAt=Date.now()+350;render();window.scrollTo(0,0);
  }});
  main.append(encounterIntro.element);return;
 }
 const root=renderRpgBattle({document,state,onAction:(action,battleId,turn)=>{
  if(battleInputBlocked()||modal.open)return;
  const beforeState=state;ui.battleAnimating=true;
  if(!act({type:'RPG_BATTLE_ACTION',action,battleId,turn},{render:false})){ui.battleAnimating=false;return;}
  const afterState=state;clearTimeout(combatArmTimer);combatArmTimer=null;
  const menu=document.querySelector('#adventure-menu-toggle');if(menu)menu.disabled=true;
  try{battleAnimation=mountBattleTurn({document,root,beforeState,afterState,action,reducedMotion:state.settings.reducedMotion||window.matchMedia?.('(prefers-reduced-motion: reduce)').matches,onComplete:()=>{
   if(!ui.battleAnimating||ui.view!=='combat'||state!==afterState)return;
   battleAnimation=null;ui.battleAnimating=false;ui.combatReadyAt=Date.now()+180;render();
  }});}catch{battleAnimation?.destroy();battleAnimation=null;ui.battleAnimating=false;ui.combatReadyAt=Date.now()+180;render();}
 },onContinue:()=>{if(!battleInputBlocked())continueAfterBattle();},onTown:()=>{if(battleInputBlocked())return;if(state.rpg?.battle?.kind==='field'&&state.rpg.battle.status==='lost'){wakeAtChurch();return;}travelArea('town:'+state.currentChapter);act({type:'RPG_REST'});}});
 main.append(root);
 const remaining=(ui.combatReadyAt??0)-Date.now();
 if(battle&&remaining>0){
  const buttons=[...root.querySelectorAll('button')].map(button=>[button,button.disabled]);
  for(const[button]of buttons)button.disabled=true;
  combatArmTimer=setTimeout(()=>{combatArmTimer=null;if(ui.view!=='combat'||state.rpg?.battle?.id!==battle.id)return;for(const[button,disabled]of buttons)if(button.isConnected)button.disabled=disabled;},remaining);
 }
}
function battleInputBlocked(){return ui.battleAnimating||Date.now()<(ui.combatReadyAt??0);}
function maybeFieldEncounter(){const pos=expeditionPosition();if(pos.mapId!=='world')return false;const desert=isDesert(pos);if((ui.desertGrace??0)>0){ui.desertGrace--;return false;}if(desert){ui.desertSteps=(ui.desertSteps??0)+1;if(ui.desertSteps===1)toast('砂漠の奥から、とてつもない気配がする……');if(ui.desertSteps<2)return false;ui.desertSteps=0;return startFieldBattle('desert');}ui.desertSteps=0;ui.roadSteps=(ui.roadSteps??0)+1;const enc=getFieldEncounter('road',state.currentChapter),threshold=state.rpg.attempts[enc.id]?20:4;if(ui.roadSteps<threshold)return false;ui.roadSteps=0;return startFieldBattle('road');}
function startFieldBattle(kind){worldControls?.stop();if(act({type:'RPG_FIELD_START',kind,chapterId:state.currentChapter},{view:'combat'})){ui.battleQuestKey=null;window.scrollTo(0,0);return true;}return false;}
function openShop(){if(!ensureStarted())return;ui.room=null;if(act({type:'RPG_TRAVEL',mapId:'shop:'+state.currentChapter},{view:'shop'}))window.scrollTo(0,0);}
function leaveShop(){const shop=getTownTravelFeatures(state.currentChapter).find(f=>f.type==='shop');if(!act({type:'RPG_TRAVEL',mapId:'town:'+state.currentChapter},{render:false,worldPosition:{x:shop.x,y:shop.y+1,direction:0,walkFrame:0}}))return;ui.room=null;ui.view='world';ui.expeditionPosition=null;render();window.scrollTo(0,0);}
function renderShopView(main){main.append(renderRpgShop({document,state,onBuy:gearId=>act({type:'RPG_BUY',gearId}),onEquip:gearId=>act({type:'RPG_EQUIP',gearId}),onLeave:leaveShop}));}
function expeditionInstruction(){const pos=expeditionPosition();if(isDesert(pos))return '危険な砂漠！ とても強い気配。戦うなら覚悟を、にげるも選べます。';const map=getRpgMap(pos.mapId),record=state.questStates[state.activeQuestKey],q=questById[record?.questId];if(pos.mapId.startsWith('cave:'))return record?.completed?'結果を村人へ届けよう。下の出口から外へ。':entryEncounter()?'奥の門番へ歩き、近くで「話す」。':'用事のつづきは「くわしく」から。下の出口で外へ。';if(!q)return '好きな町の入口へ歩こう。近くで「話す」。';const returning=record.completed,f=map.features.find(x=>x.targetMapId===(returning?'town:':'cave:')+q.chapterId);if(!f)return '好きな町へ歩こう。';const directions=[f.x===pos.x?'':f.x>pos.x?'右':'左',f.y===pos.y?'':f.y>pos.y?'下':'上'].filter(Boolean).join('・');return `${returning?'報告へ：':''}${f.label}へ${directions?'、'+directions+'へ歩こう。':'。近くで「話す」。'}`;}
function renderExpedition(main){const pos=expeditionPosition(),map=getRpgMap(pos.mapId);main.append(explorationObjective(expeditionInstruction()));const canvas=h('canvas',{width:400,height:288,class:'world-canvas expedition-canvas',role:'img','aria-label':map?.title??'世界地図',onClick:e=>{const r=canvas.getBoundingClientRect(),current=expeditionPosition(),camera=renderRpgMap(canvas,visualState(),current),x=camera.x+(e.clientX-r.left)*25/r.width,y=camera.y+(e.clientY-r.top)*18/r.height,feature=map.features.find(f=>Math.abs(f.x+.5-x)<1.3&&Math.abs(f.y+.5-y)<1.3);if(feature){if(Math.abs(feature.x-current.x)+Math.abs(feature.y-current.y)<=3)interactFeature(feature);else toast((feature.label??feature.title??'入口')+'へ十字キーで近づこう。');}}});renderRpgMap(canvas,visualState(),pos);main.append(h('section',{class:'card world-card expedition-card expedition-map exploration-stage'},h('div',{class:'world-view'},canvas),controlPanel(),p('入口や魔物の近くで「話す」。近道はメニューへ。','world-position-status')));}


function automaticEncounter(){const log=state.rpg?.eventLog??[],escaped=new Set(log.filter(e=>e.kind==='battle-action'&&e.status==='fled').map(e=>e.battleId)),deferred=new Set(log.filter(e=>e.kind==='battle-start'&&escaped.has(e.battleId)).map(e=>e.encounterId));return getAvailableEncounters(state).find(e=>e.recordKey===state.activeQuestKey&&e.checkpoint>0&&e.available&&!e.defeated&&!deferred.has(e.id));}

function gearName(id){return equipmentById[id]?.name??getRpgView(state).shop.find(g=>g.id===id)?.name??'なし';}
